class Order:  # Aggregate Root
    def __init__(self, order_id: OrderId, allocation: int):
        self._id = order_id
        self._lines: list[OrderLine] = []
        self._allocation = allocation
        self._confirmed = False

    def add_line(self, product_id: ProductId, qty: Quantity) -> None:
        # Enforce invariant: total quantity <= allocation
        new_total = sum(l.quantity for l in self._lines) + qty.value
        if new_total > self._allocation:
            raise AllocationExceededError(
                f"Cannot add {qty.value} units: exceeds allocation of {self._allocation}"
            )
        self._lines.append(OrderLine(product_id, qty))

    def confirm(self) -> None:
        # Enforce invariant: order must have at least one line
        if not self._lines:
            raise EmptyOrderError("Cannot confirm an order with no lines")
        self._confirmed = True

    @property
    def id(self) -> OrderId:
        return self._id

# Correct: reference by identity
@dataclass
class Order:
    id: OrderId
    customer_id: CustomerId  # ID only — no object reference
    lines: list[OrderLine]

# Wrong: object reference across aggregate boundary
@dataclass
class Order:
    id: OrderId
    customer: Customer  # Pulls Customer into Order's loading context

class OrderRepository(ABC):
    @abstractmethod
    def get(self, order_id: OrderId) -> Order: ...

    @abstractmethod
    def save(self, order: Order) -> None: ...

    @abstractmethod
    def next_id(self) -> OrderId: ...
